INSERT INTO erp_rfp_proof_of_payment(rfp_ref,reference,paid_at,actor)
SELECT a.record_no, a.file_name,
       (SELECT MIN(s.paid_date) FROM erp_payment_settlements s
         WHERE s.request_no=a.record_no AND s.status<>'VOID'),
       a.uploaded_by
  FROM erp_attachments a
 WHERE a.record_type='PAYMENT_PROOF' AND a.active=1
   AND NOT EXISTS (SELECT 1 FROM erp_rfp_proof_of_payment p
                    WHERE p.rfp_ref=a.record_no AND p.reference=a.file_name);

